<div class="space-y-5"><h1 class="text-3xl font-bold">Logs</h1><form class="grid md:grid-cols-4 gap-3"><select name="category" class="bg-slate-800 p-2 rounded"><option value="">Todas las categorías</option><?php foreach(['authentication','administration','reseller','api','balancer','stream','ffmpeg','import','tmdb','database','security','job','error'] as $value):?><option <?=$filters['category']===$value?'selected':''?>><?=$value?></option><?php endforeach?></select><select name="level" class="bg-slate-800 p-2 rounded"><option value="">Todos los niveles</option><?php foreach(['debug','info','notice','warning','error','critical'] as $value):?><option <?=$filters['level']===$value?'selected':''?>><?=$value?></option><?php endforeach?></select><input name="query" value="<?=htmlspecialchars($filters['query'])?>" placeholder="Buscar" class="bg-slate-800 p-2 rounded"><button class="bg-cyan-600 rounded">Filtrar</button></form><a class="inline-block bg-slate-700 px-3 py-2 rounded" href="/logs/export?<?=http_build_query($filters)?>">Exportar CSV</a><div class="space-y-2"><?php foreach($logs as $log):?><article class="bg-slate-900 border border-slate-800 rounded p-3"><div class="flex gap-3 text-xs"><strong><?=htmlspecialchars($log['category'])?></strong><span><?=htmlspecialchars($log['level'])?></span><span class="ml-auto"><?=$log['created_at']?></span></div><p class="mt-2"><?=htmlspecialchars($log['message'])?></p><div class="text-xs text-slate-500"><?=htmlspecialchars($log['correlation_id']??'')?> <?=htmlspecialchars($log['ip']??'')?></div></article><?php endforeach?></div></div>
